        throw new Error(`Timed out waiting for city worktree lock (${holder})`);
      }

      const waitMs = Math.min(2000, 250 + attempt * 200 + Math.floor(Math.random() * 250));
      sleepMs(waitMs);
      attempt++;
    }
  }
}

