// ── Extract per-model observations from a single deliberation artifact ──
function extractObservations(artifact) {
  const observations = [];
  const question = artifact.question || '';
  const version = artifact.version || 1;
  const file = artifact._file;
  const domain = classifyDomain(question);

  // V2 format: clusters with outcomes
  if (artifact.clusters) {
