        const entries = cluster.outcomes[status] || [];
        for (const entry of entries) {
          observations.push({
            model: entry.model,
            family: entry.family,
            status,
            question,
            domain,
            version,
            file,
            clusterSize: cluster.models?.length || 0,
            clusterModels: cluster.models || [],
            position: entry.position || '',
          });
        }
      }
    }
    // Also check minority reports for position text
    if (artifact.minorityReport) {
      for (const mr of artifact.minorityReport) {
        for (const m of (mr.minorities || [])) {
          const obs = observations.find(o => o.model === m.model && o.file === file);
          if (obs && m.position) obs.position = m.position;
        }
      }
    }
  }

  // V3 format: teams with individual positions + per-model outcome labels
  if (artifact.teams) {
    const outcomes = artifact.modelOutcomes || {};
