      if (!team.models) continue;
      for (const model of team.models) {
        const isDA = model === team.daModel;
        const outcome = outcomes[model];
        // Use per-model label if available, otherwise fall back to PARTICIPATED
        const status = outcome?.status && ['BEDROCK', 'TRANSFORMED', 'BROKEN'].includes(outcome.status)
