          family: posEntry?.family || null,
          status,
          question,
          domain,
          version,
          file,
          teamSize: team.models?.length || 0,
          teamModels: team.models || [],
          isDA,
          teamPosition: team.teamPosition || '',
          position: posEntry?.text || '',
          similarity: outcome?.similarity || null,
